const body = $json.body ?? $json;
const raw = body.message ?? body.command ?? body.prompt ?? body.text ?? '';

if (typeof raw !== 'string' || !raw.trim()) {
  return [{
    json: {
      ok: false,
      error: 'COMMAND_REQUIRED',
      message: 'Envie um comando no campo message, command, prompt ou text.'
    }
  }];
}

const command = raw.trim();
const requestId = body.request_id ?? `rup-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;

return [{
  json: {
    ok: true,
    request_id: requestId,
    command,
    source: body.source ?? 'webhook',
    received_at: new Date().toISOString()
  }
}];
